tz_def('MSG_PROMOTE_BODY', "سلام %s!\n\nبه اطلاع می‌رساند که حمله موفقی به بازیکن <a href=\"spieler.php?uid=%s\">%s</a> انجام شد که سفارت او را چنان آسیب زد که دیگر قادر به رهبری اتحاد شما نیست.\n\nاز آنجا که سطح سفارت شما کافی است، به‌طور خودکار به‌عنوان رهبر جدید اتحاد با تمام وظایف و مسئولیت‌های آن انتخاب شدید.\n\nبا احترام،\n<i>ربات سرور :)</i>");
