tz_def('MSG_FORCED_LEAVE_BODY', "سلام %s!\n\nبه اطلاع می‌رساند که به دلیل یک حمله موفق و نابودی آخرین سفارت شما، مجبور به ترک اتحاد خود شده‌اید.\n\nبرای بازگشت به این اتحاد، باید سفارت جدیدی بسازید و از <a href=\"spieler.php?uid=%s\">رهبر تازه انتخاب‌شده</a> بخواهید دوباره برای شما دعوت‌نامه بفرستد.\n\nبا احترام،\n<i>ربات سرور :)</i>");
