tz_def('MANUAL_NF_ENABLED', "فعال");
tz_def('MANUAL_NF_DISABLED', "غیرفعال");
tz_def('MANUAL_NF_T_11', "نمایش واحه در پروفایل");
tz_def('MANUAL_NF_T_12', "پیام دعوت به اتحاد");
tz_def('MANUAL_NF_T_13', "سازوکار جدید اتحاد و سفارت");
tz_def('MANUAL_NF_T_14', "پیام نوشته جدید انجمن");
tz_def('MANUAL_NF_T_15', "تصاویر قبایل در پروفایل");
tz_def('MANUAL_NF_T_16', "تصاویر مولتی‌هانترها در پروفایل");
tz_def('MANUAL_NF_T_17', "نمایش کتیبه در پروفایل");
tz_def('MANUAL_NF_T_18', "نمایش شگفتی جهان در پروفایل");
tz_def('MANUAL_NF_T_20', "اهداف منجنیق");
tz_def('MANUAL_NF_T_21', "راهنمای طبیعت و ناتارها");
tz_def('MANUAL_NF_T_22', "محل پیوندهای مستقیم");
tz_def('MANUAL_NF_T_23', "مدال بازیکن کهنه‌کار");
tz_def('MANUAL_NF_T_24', "مدال بازیکن کهنه‌کار ۵ ساله");
tz_def('MANUAL_NF_T_25', "مدال بازیکن کهنه‌کار ۱۰ ساله");
tz_def('MANUAL_NF_T_26', "مدال‌های ویژه");
tz_def('MANUAL_NF_D_11', "اگر در دهکده واحه تصرف‌شده‌ای باشد، در پروفایل بازیکن کنار دهکده مربوط همراه با نوع منبع و پاداش تولید آن نمایش داده می‌شود. این امکان در تراوین T4 معرفی شد.");
tz_def('MANUAL_NF_D_12', "اگر برای بازیکنی دعوت‌نامه پیوستن به اتحاد ارسال شود، با یک پیام داخل بازی به او اطلاع داده می‌شود.");
tz_def('MANUAL_NF_D_13', "<h2>مقدمه</h2><br> سازوکار سفارت و اتحاد همیشه کمی شبیه تقلب به نظر می‌رسید؛ به‌ویژه اینکه ساختمان سفارت «ظرفیت» مشخصی دارد، یعنی بسته به سطح سفارت فقط ۳/۶/۹/۱۲/... و تا ۶۰ عضو می‌توانند در اتحاد باشند. <br><br> اما وقتی سفارت سطح ۲۰ داشتید و به ۶۰ عضو می‌رسیدید، می‌توانستید ساختمان را کاملاً تخریب کنید و هیچ اتفاقی نمی‌افتاد. فقط نمی‌توانستید اتحاد را عوض کنید. ویژگی ظرفیت سفارت دیگر اعمال نمی‌شد؛ اگر اعمال می‌شد، حتی نمی‌توانستید آن را یک سطح به ۱۹ پایین بیاورید، چون با ۶۰ عضو کامل، سفارت سطح ۱۹ دیگر گنجایش آنها را نداشت. <br><br> پس تصمیم گرفتم بازی را کمی جذاب‌تر کنم و سفارت را به مهره‌ای مهم‌تر روی صفحه تبدیل کنم. <br><br> <h2>سازوکار جدید</h2><br> برای جذاب‌تر شدن، مجموعه کاملاً جدیدی از قوانین برای تخریب و نابودی سفارت در نبرد طراحی شده است. کمی پیچیده است اما دقیقاً ویژگی «ظرفیت» اتحاد را منعکس می‌کند. <br><br> تغییر اصلی این است که بازیکنان دیگر نمی‌توانند سفارت خود را بدون پیامد تخریب کنند. برای عضو اتحاد یعنی سفارت هرگز نباید زیر سطح ۱ برود؛ اگر برود، هشدار می‌گیرد و سپس از اتحاد خارج می‌شود. <br><br> برای بنیان‌گذاران اتحاد چالش بیشتری وجود دارد، چون آنها باید اتحاد را سرپا نگه دارند. برای آنها تخریب سفارت تا سطحی که دیگر گنجایش اعضای فعلی را نداشته باشد مجاز نیست. <br><br> حال اگر بازیکنان یا اتحادهای دیگر به دهکده بنیان‌گذار که سفارت در آن است حمله کنند و سفارت را با منجنیق و دژکوب هدف بگیرند، دردسر بزرگی پیش می‌آید. اگر در دهکده‌های دیگر بنیان‌گذار سفارتی با سطح کافی برای همه اعضا نباشد، اتحاد ممکن است پراکنده شود. تنها استثنا وقتی است که عضو دیگری سفارت به‌اندازه کافی توسعه‌یافته داشته باشد؛ در این صورت آن عضو خودکار به رهبری انتخاب می‌شود و اتحاد را نجات می‌دهد. اگر چنین بازیکنی پیدا نشود، اتحاد کاملاً پراکنده می‌شود. <br><br> <h2>اطلاعات تکمیلی</h2><br> برای اطلاعات تصویری و دقیق‌تر درباره این سیستم می‌توانید این <a href=\"https://docs.google.com/presentation/d/1KN1qVAlxVj7aAN6F9QkRai1oliajfxKPIaJ4MSodUac/edit#slide=id.p\" target=\"_blank\">ارائه گوگل</a> را ببینید.");
tz_def('MANUAL_NF_D_14', "اگر بازیکن حداقل یک پیام در موضوعی از انجمن بگذارد، هر بار که شخص دیگری پیام جدیدی در همان موضوع بگذارد، پیام داخل بازی دریافت می‌کند (یعنی عملاً «مشترک» آن موضوع می‌شود).");
tz_def('MANUAL_NF_D_15', "با این امکان، هر بازیکن می‌تواند تصویر قبیله خود را همراه با توضیح کوتاهی (رومی‌ها، توتن‌ها، گول‌ها) به توضیحات پروفایل اضافه کند.");
tz_def('MANUAL_NF_D_16', "در واقع این امکان برای بازیکنان کاربردی ندارد و فقط برای مدیران و مولتی‌هانترهاست. با آن می‌توانند تصاویر جالب گوناگونی را همراه با توضیح به پروفایل خود اضافه کنند.");
tz_def('MANUAL_NF_D_17', "اگر در یکی از دهکده‌ها کتیبه‌ای باشد، در پروفایل بازیکن کنار دهکده مربوط نمایش داده می‌شود. این امکان در تراوین T4 معرفی شد.");
tz_def('MANUAL_NF_D_18', "اگر در دهکده محلی برای ساخت شگفتی جهان باشد، در پروفایل کنار دهکده مربوط نمایش داده می‌شود. این امکان در تراوین T4 معرفی شد.");
tz_def('MANUAL_NF_D_19', "حالت تعطیلات به شما امکان می‌دهد در غیبت طولانی، امپراتوری خود را از هرگونه اقدام خصمانه بازیکنان دیگر محافظت کنید. البته شرایطی دارد که باعث عقب افتادن توسعه امپراتوری شما می‌شود. این امکان در تراوین T4 معرفی شد.");
tz_def('MANUAL_NF_D_20', "اگر منجنیق‌ها را با حمله عادی بفرستید، می‌توانید در اردوگاه ببینید چه اهدافی برای حمله تعیین کرده‌اید. این امکان در تراوین T4 معرفی شد.");
tz_def('MANUAL_NF_D_21', "با کمک این بخش از راهنما می‌توانید توضیحات نیروهای طبیعت و ناتارها را پیدا کنید.");
